/* FaLe One service worker: offline app shell + Web Share Target.
 * Never caches anything personal: API responses (/api/…, other origins) are not touched at all, and
 * decrypted content never exists as a network response (it lives in memory as Blobs). Offline copies of files
 * are the server's CIPHERTEXT chunks in IndexedDB (see js/idb.js), not Cache Storage. */
const VERSION = 'one-98a9e2853d';
const CACHE = `fale-one-${VERSION}`;
const VENDOR_CACHE = 'fale-one-pdfjs-v1'; // pdf.js cmaps / fonts: cached on first use, kept across app updates

// ASSETS-START (generated by scripts/sync-one-shared.mjs – do not edit by hand)
const ASSETS = [
  "./",
  "./css/fale-tokens.css",
  "./css/one.css",
  "./icons/apple-touch-icon.png",
  "./icons/favicon-32.png",
  "./icons/favicon.svg",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/icon-maskable-192.png",
  "./icons/icon-maskable-512.png",
  "./index.html",
  "./js/app.js",
  "./js/auth.js",
  "./js/boot.js",
  "./js/config.js",
  "./js/dom.js",
  "./js/engine.js",
  "./js/export.js",
  "./js/i18n-en.js",
  "./js/i18n.js",
  "./js/idb.js",
  "./js/keys.js",
  "./js/media.js",
  "./js/pdfview.js",
  "./js/shared/one/api.js",
  "./js/shared/one/crypto.js",
  "./js/shared/share/crypto.js",
  "./js/shared/sync/crypto.js",
  "./js/takeout.js",
  "./js/unzip.js",
  "./js/views/common.js",
  "./js/views/drive.js",
  "./js/views/fotos.js",
  "./js/views/grid.js",
  "./js/views/notfall.js",
  "./js/views/onboarding.js",
  "./js/views/search.js",
  "./js/views/settings.js",
  "./js/views/uploads.js",
  "./js/views/viewer.js",
  "./js/worker.js",
  "./manifest.webmanifest",
  "./vendor/dompurify/purify.min.js",
  "./vendor/fonts/BricolageGrotesque-Bold.woff",
  "./vendor/pdfjs/pdf.min.mjs",
  "./vendor/pdfjs/pdf.worker.min.mjs"
];
// ASSETS-END

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(ASSETS.map(a => new Request(a, { cache: 'reload' })));
    // no skipWaiting(): a new version takes over when all tabs are closed (no mix of old and new modules)
  })());
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('fale-one-') && k !== CACHE && k !== VENDOR_CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

// ---------------------------------------------------------------- share target (manifest "share_target")
function openInbox() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open('fale-one-inbox', 1);
    req.onupgradeneeded = () => { if (!req.result.objectStoreNames.contains('files')) req.result.createObjectStore('files', { autoIncrement: true }); };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function handleShare(request) {
  const scope = new URL(self.registration.scope).pathname;
  try {
    const form = await request.formData();
    let total = 0;
    const files = form.getAll('files').filter(f => f && typeof f === 'object' && f.size >= 0).slice(0, 500)
      .filter(f => (total += f.size) <= 4 * 1024 * 1024 * 1024);
    if (files.length) {
      // the files stay on this device until the app has picked them up (then the inbox is cleared)
      const db = await openInbox();
      await new Promise((res, rej) => { const tx = db.transaction('files', 'readwrite'); tx.objectStore('files').add({ at: Date.now(), files }); tx.oncomplete = res; tx.onerror = () => rej(tx.error); });
      db.close();
    }
    return Response.redirect(`${scope}?shared=1#/drive`, 303);
  } catch {
    return Response.redirect(`${scope}#/drive`, 303);
  }
}

self.addEventListener('fetch', event => {
  const req = event.request;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;          // the API and Supabase: never intercepted
  if (url.pathname.includes('/api/') || url.pathname.includes('/__test/')) return;
  if (req.method === 'POST' && url.pathname.endsWith('/share-target')) { event.respondWith(handleShare(req)); return; }
  if (req.method !== 'GET') return;
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      try {
        const res = await fetch(req);
        if (res.ok && url.pathname === new URL(self.registration.scope).pathname) cache.put('./', res.clone());
        return res;
      } catch {
        return (await cache.match('./')) || (await cache.match('./index.html')) || new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
      }
    })());
    return;
  }
  if (/\/vendor\/pdfjs\/(cmaps|standard_fonts|iccs|wasm)\//.test(url.pathname)) {
    event.respondWith((async () => {
      const cache = await caches.open(VENDOR_CACHE);
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok && res.type === 'basic') cache.put(req, res.clone());
      return res;
    })());
    return;
  }
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try { return await fetch(req); } catch { return new Response('', { status: 504, statusText: 'Offline' }); }
  })());
});
